BEGIN;
UPDATE f360.locations SET id = '488d8555-4623-4919-b713-a708852674d5' WHERE type = 'transit' AND id <> '488d8555-4623-4919-b713-a708852674d5';
  SELECT 'woo_production', 'Tienda en línea', 'https://fuxiaballerinas.com', id, false, true, false FROM f360.locations WHERE name = 'Bodega CDMX' AND type = 'warehouse';
GRANT EXECUTE ON FUNCTION public.f360_legacy_channel_frozen(uuid) TO anon;
DO $s$ DECLARE r record; m bigint; BEGIN
  FOR r IN SELECT n.nspname || '.' || c.relname AS t, a.attname AS col, pg_get_serial_sequence(n.nspname || '.' || c.relname, a.attname) AS seq
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum > 0
